const item = $input.item.json;
const name = (item.researchCandidateName || '').toString().trim();
const now = new Date().toISOString();

// Technischer, einzelkandidat-bezogener Recherche-Adapter: wird vom
// fachlichen Subworkflow "Due Diligence" separat je Kandidat aufgerufen
// (echte Parallelzweige statt einer gemeinsamen Liste in einem Node), damit
// ein fehlgeschlagener Zweig isoliert bleibt und nicht die Recherche der
// uebrigen Kandidaten verhindert. Es wird explizit keine echte Qlik-Analyse
// oder Websuche durchgefuehrt; jeder Eintrag ist klar als simulierte
// Dummy-Quelle gekennzeichnet.
if (!name) {
  throw new Error('researchCandidateName fehlt - kein Kandidat fuer diese Recherche-Ausfuehrung uebergeben.');
}

const seed = name.length;
const researchResult = {
  candidate: name,
  club: `Dummy-Verein ${seed}`,
  contract: 'Simulierter Vertrag bis 30.06.2027 (keine echte Recherche)',
  marketValue: `${(5 + (seed % 5)).toFixed(1)} Mio. EUR (simuliert)`,
  injuries: 'Keine bekannten Verletzungen (simuliert, keine echte Recherche)',
  news: [`Simulierte Meldung zu ${name} (keine echte Websuche durchgefuehrt)`],
  source: 'Dummy-Quelle (keine echte Web-/Qlik-Recherche)',
  timestamp: now,
  confidence: 0.4
};

return [{ json: { ...item, researchResult } }];
